#!/usr/bin/env bash
# The hero's full frame set drawn by one model (GPT image, white sheets) so every action matches.
# Usage: MK_KEYS="key" tools/hero2.sh   -> gen/raw_h2_move.png, raw_h2_atk.png, raw_h2_act.png (retries dark sheets)
export MK_MODELS=${MK_MODELS:-"cx/gpt-image-2 cx/gpt-6-sol-image cx/gpt-image-1.5"}
H="one wandering swordsman, a lean man about thirty with a short dark beard and long black hair tied back: wide conical woven bamboo hat, tattered dark indigo knee-length robe with a grey sash, loose charcoal-grey trousers, black cloth boots, a long vermilion red scarf, a straight double-edged jian sword with a plain dark hilt held in the right hand"
S="Style: traditional Chinese ink wash painting (sumi-e) 2D game animation sprite sheet, bold expressive black brush outlines, muted desaturated colours with the vermilion scarf as the only bright accent, cloth shaded in 3 to 4 tones. Every frame shows the SAME character with identical face, costume, colours, proportions and size, full body, side-on three-quarter view facing RIGHT, strong exaggerated line of action, scarf, hair and robe trailing to show motion. Frames laid out in an even grid with wide gaps, never touching or overlapping. The whole sheet has a perfectly plain flat pure white #FFFFFF background, evenly lit like a scanned model sheet, every figure closed by a continuous black outline, no ground, no shadow, no glow, no vignette, no text, no numbers, no frame borders, no speed lines, no slash effects."
good() { [ -s "$1" ] && python -c "
import sys, numpy as np
from PIL import Image
im = np.asarray(Image.open(sys.argv[1]).convert('RGB')) / 255.0
e = np.concatenate([im[:8].reshape(-1, 3), im[-8:].reshape(-1, 3), im[:, :8].reshape(-1, 3), im[:, -8:].reshape(-1, 3)])
sys.exit(0 if np.median(e) > 0.85 and (e.min(axis=1) > 0.7).mean() > 0.9 else 1)" "$1"; }
one() {
  for try in 1 2 3 4; do
    if good gen/raw_$1.png; then echo "$1 ok"; return; fi
    echo "$1 try $try"; tools/gen.sh "$1" "$2" "$S"; sleep 2
  done
}
one h2_move "SPRITE SHEET of $H. Twelve frames in three rows of four. Row 1, RUN CYCLE part one, sprinting right leaning far forward with the sword trailing low behind: 1 right foot reaching far forward about to land, 2 weight sinking on the bent right leg, 3 pushing off the right leg with the left knee driving forward, 4 airborne with both feet off the ground. Row 2, RUN CYCLE part two: 5 left foot reaching far forward about to land, 6 weight sinking on the bent left leg, 7 pushing off the left leg with the right knee driving forward, 8 airborne with both feet off the ground. Row 3, IDLE BREATHING standing relaxed with the sword lowered: 9 neutral, 10 inhaling with shoulders rising and scarf lifting slightly, 11 fully inhaled standing tallest, 12 exhaling with shoulders sinking and knees soft."
one h2_atk "SPRITE SHEET of $H. Twelve frames in three rows of four, a three-slash sword combo. Row 1, FIRST SLASH horizontal: 1 anticipation coiled with the sword pulled far back at the left hip, 2 the slash in mid-swing with torso twisting and sword pointing forward, 3 follow-through with the sword arm flung wide to the right, 4 recovery stepping back to guard. Row 2, SECOND SLASH diagonal downward: 5 anticipation with the sword raised high over the right shoulder, 6 mid-swing cutting downward while stepping forward, 7 follow-through crouched low with the sword near the ground, 8 rising from the crouch. Row 3, FINISHER: 9 anticipation spinning with back half turned and robe flaring, 10 full spinning slash with robe and scarf whirling in a circle, 11 deep forward lunge thrust with the sword fully extended ahead, 12 holding the lunge then pulling back."
one h2_act "SPRITE SHEET of $H. Twelve frames in three rows of four, action poses. Row 1: 1 guard stance with the sword upright in front of the body, 2 bracing behind the sword as a blow lands leaning back slightly, 3 hit recoil staggering backwards with the head thrown back, 4 dropping to one knee wounded leaning on the sword. Row 2: 5 crouching low before a dash, 6 low horizontal dash with the body almost flat and the scarf streaming, 7 skidding to a stop out of the dash with one hand on the ground, 8 throwing the sword forward with the arm fully extended and the empty hand open. Row 3: 9 empty right hand reaching out to call the sword back, 10 catching the returning sword overhead, 11 gathering inner force with the sword held vertical before the face and robe billowing upward, 12 releasing the force with the sword thrust to the sky and arms wide."
echo HERO2 DONE
